import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]; p=root/'game/data/expansion.json'
talents=[]
for tier,(slot,opts) in enumerate([(0,[('focus','Hội tụ','Kiếm quang +25% sát thương.'),('breaker','Phá giáp','Kiếm quang phá khiên như Tinh linh.')]),(1,[('restoration','Nguồn sống','Hồi phục +35% lượng máu.'),('barrier','Che chở','Hồi phục tạo khiên bằng 15% HP tối đa, tồn tại 5 giây.')]),(2,[('nova','Bùng sáng','Tinh linh +25% sát thương.'),('flow','Lưu chuyển','Tinh linh chỉ tốn 25 SP và hồi chiêu nhanh hơn 20%.')])]):
 for key,name,desc in opts:talents.append(dict(id=key,name=name,description=desc,slot=slot,level=tier+2,gold=40+tier*20,shards=tier+1))
traits={'sword_1':('spring','Mỗi đòn thường trúng hồi thêm 2 SP.'),'sword_2':('riposte','Thủ đòn thành công tăng 30% sát thương đòn vũ khí tiếp theo trong 4 giây; kỹ năng hồi nhanh hơn 8%.'),'spear_1':('execute','Tăng 20% sát thương vũ khí khi mục tiêu còn dưới 35% HP.'),'spear_2':('pierce','Đòn vũ khí xuyên một phần khiên: gây 70% thay vì 35%; kỹ năng hồi nhanh hơn 8%.'),'staff_1':('mending','Kỹ năng hồi phục mạnh hơn 15%.'),'staff_2':('conduit','Kỹ năng hoàn lại 4 SP tại marker trúng; kỹ năng hồi nhanh hơn 8%.')}
base=json.loads((root/'game/data/catalog.json').read_text());branches=[]
names=[('Suối lạc quang','Gốc rễ ký ức'),('Đường than nguội','Lò lửa cuối cùng'),('Bờ hồ lặng','Dưới mặt gương'),('Lối chuông gió','Tàn tinh rơi'),('Hành lang cũ','Lời hứa bình minh')]
texts=[('Lumi: Có tiếng gọi nhỏ bên dòng suối.','Eira: Ta sẽ đưa hạt sáng này về nơi nó thuộc về.','Cổ thụ: Rễ cây nhớ cả những bước chân đã mất.','Eira: Ký ức không cần phải trở thành xiềng xích.'),('Ash: Những dấu chân này dẫn khỏi chiến trường.','Ryn: Vẫn có người từng chọn cứu lấy nhau.','Ryn: Lò rèn chưa tắt, chỉ đang đợi một bàn tay.','Ash: Ngọn lửa này sẽ sưởi ấm, thay vì thiêu đốt.'),('Mira: Một gợn sóng đang đi ngược chiều gió.','Lumi: Đó là lời chào từ phía bên kia.','Mira: Đừng rút kiếm với bóng mình. Hãy lắng nghe.','Mira: Ta có thể mang theo nỗi buồn mà vẫn bước tiếp.'),('Eira: Mỗi chiếc chuông mang một cái tên.','Ryn: Hôm nay chúng lại được gọi thành tiếng.','Ash: Ngôi sao rơi xuống đây từ rất lâu.','Eira: Ánh sáng nhỏ cũng đủ chỉ đường trong đêm.'),('Mira: Những bức tường này lưu giữ tiếng cười.','Eira: Nơi này từng là một mái nhà.','Eira: Mình đã hứa sẽ quay lại cùng mọi người.','Lumi: Vậy thì bình minh của chúng ta đã bắt đầu.')]
for i,b in enumerate(base['stages']):
 for route in range(2):
  s=dict(b);sid=6+i*2+route;s.update(id=sid,name=names[i][route],base_stage=b['id'],kind='branch',requires=[b['id'] if route==0 else sid-1],enemy_hp=round(b['enemy_hp']*(1.1+.15*route)),boss_hp=round(b['boss_hp']*(1.1+.15*route)),gold=b['gold']+15,xp=b['xp']+10,first_gold=40,before=texts[i][route*2],after=texts[i][route*2+1]);branches.append(s)
challenges=[]
for sid,name,idx,waves,unlock in [(101,'Săn cổ thụ',0,1,1),(102,'Tháp sáu đợt',1,6,2),(103,'Tam vệ bình minh',2,3,3)]:
 b=dict(base['stages'][idx]); b.update(id=sid,name=name,base_stage=idx+1,kind='challenge',requires=[unlock],gold=60+idx*30,xp=35+idx*15,first_gold=0,before='Ash: Thử thách này dành cho những người đã sẵn sàng. Hãy chuẩn bị kỹ năng và đồng hành.',after='Eira: Chúng ta đã tiến thêm một bước.',waves=[dict(boss=(sid==103 or j==waves-1),hp=round((b['boss_hp'] if sid==103 or j==waves-1 else b['enemy_hp'])*(1+.12*j)),atk=b['boss_atk'] if sid==103 or j==waves-1 else b['enemy_atk'],mechanic=['smash','shield','counter'][j%3] if sid==103 else b['mechanic']) for j in range(waves)],cores=1+idx)
 if sid == 103:
  for j,row in enumerate(b['waves']):
   row.update(name=['Cổ thụ thức tỉnh','Hộ vệ than hồng','Ảo ảnh thủy triều'][j],enemy_type=['golem','guardian','wolf'][j],zone=['forest','ruins','lake'][j],element=['nature','fire','water'][j])
 challenges.append(b)
achievements=[dict(id='arms',name='Kho vũ khí',metric='items',target=6,gold=100,shards=4,cores=1),dict(id='wardens',name='Năm người giữ cửa',metric='bosses',target=5,gold=180,shards=6,cores=2),dict(id='bonds',name='Bạn đồng hành',metric='ranks',target=4,gold=120,shards=4,cores=2),dict(id='paths',name='Người tìm ký ức',metric='branches',target=10,gold=200,shards=8,cores=3),dict(id='trial_100',name='Bước vào thử thách',metric='score',target=100,gold=80,shards=3,cores=1),dict(id='trial_500',name='Ánh sáng bền bỉ',metric='score',target=500,gold=180,shards=6,cores=2)]
p.write_text(json.dumps(dict(version=1,talents=talents,traits={k:dict(id=v[0],description=v[1]) for k,v in traits.items()},stages=branches+challenges,achievements=achievements,chapters=[dict(id=i+1,name=n) for i,n in enumerate(['Tiếng gọi trong rừng','Lửa còn trong tro','Mặt hồ ký ức','Chuông trên đỉnh sao','Bình minh trở lại'])]),ensure_ascii=False,indent=2)+'\n')
